import time

class HLC:
    """Hybrid logical clock (Kulkarni et al., 2014). Timestamps are (l, c) tuples."""
    def __init__(self):
        self.l, self.c = 0, 0                  # l: max wall time seen, c: logical counter

    def _pt(self) -> int:
        return time.time_ns() // 1_000_000     # physical time in ms (may drift or step)

    def now(self) -> tuple[int, int]:          # local or send event
        old = self.l
        self.l = max(old, self._pt())
        self.c = self.c + 1 if self.l == old else 0
        return (self.l, self.c)

    def update(self, ml: int, mc: int) -> tuple[int, int]:  # receive event
        old = self.l
        self.l = max(old, ml, self._pt())      # never go behind anything we've seen
        if self.l == old == ml:
            self.c = max(self.c, mc) + 1
        elif self.l == old:
            self.c += 1
        elif self.l == ml:
            self.c = mc + 1
        else:
            self.c = 0                         # our wall clock moved ahead: reset
        return (self.l, self.c)

# Tuples compare lexicographically: (1080, 0) < (1080, 1) < (1081, 0)
